window.ScripturaLexicons.BDAG_PART_0222 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-01\" data-source=\"BDAG\" data-search=\"λύτρον, ου, τό substantivo neutro resgate; preço de libertação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λύτρον, ου, τό</td><td>substantivo neutro</td><td>resgate; preço de libertação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-02\" data-source=\"BDAG\" data-search=\"λυτρόω verbo resgatar; libertar; redimir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λυτρόω</td><td>verbo</td><td>resgatar; libertar; redimir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-03\" data-source=\"BDAG\" data-search=\"λύτρωσις, εως, ἡ substantivo feminino redenção; libertação; resgate BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λύτρωσις, εως, ἡ</td><td>substantivo feminino</td><td>redenção; libertação; resgate</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-04\" data-source=\"BDAG\" data-search=\"λυτρωτής, οῦ, ὁ substantivo masculino redentor; libertador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λυτρωτής, οῦ, ὁ</td><td>substantivo masculino</td><td>redentor; libertador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-05\" data-source=\"BDAG\" data-search=\"λυχνία, ας, ἡ substantivo feminino candelabro; suporte de lâmpadas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λυχνία, ας, ἡ</td><td>substantivo feminino</td><td>candelabro; suporte de lâmpadas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-06\" data-source=\"BDAG\" data-search=\"λύχνος, ου, ὁ substantivo masculino lâmpada; luz; metáfora do olho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λύχνος, ου, ὁ</td><td>substantivo masculino</td><td>lâmpada; luz; metáfora do olho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-07\" data-source=\"BDAG\" data-search=\"λύω verbo soltar; libertar; destruir; abolir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λύω</td><td>verbo</td><td>soltar; libertar; destruir; abolir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-08\" data-source=\"BDAG\" data-search=\"Λωί̈ς, ί̈δος, ἡ nome próprio feminino Loide, avó de Timóteo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λωί̈ς, ί̈δος, ἡ</td><td>nome próprio feminino</td><td>Loide, avó de Timóteo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-09\" data-source=\"BDAG\" data-search=\"Λώτ, ὁ nome próprio masculino Ló, sobrinho de Abraão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λώτ, ὁ</td><td>nome próprio masculino</td><td>Ló, sobrinho de Abraão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-10\" data-source=\"BDAG\" data-search=\"μ´ sinal numérico numeral grego: quarenta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μ´</td><td>sinal numérico</td><td>numeral grego: quarenta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-11\" data-source=\"BDAG\" data-search=\"Μάαθ, ὁ nome próprio masculino Maat, nome genealógico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μάαθ, ὁ</td><td>nome próprio masculino</td><td>Maat, nome genealógico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-12\" data-source=\"BDAG\" data-search=\"Μαγαδάν, ἡ topônimo feminino Magadã, localidade de identificação incerta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μαγαδάν, ἡ</td><td>topônimo feminino</td><td>Magadã, localidade de identificação incerta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-13\" data-source=\"BDAG\" data-search=\"Μαγδαλά(ν) remissão veja Μαγαδάν BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μαγδαλά(ν)</td><td>remissão</td><td>veja Μαγαδάν</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-14\" data-source=\"BDAG\" data-search=\"Μαγδαληνή, ῆς, ἡ adjetivo substantivado; nome feminino Madalena; mulher de Magdala BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μαγδαληνή, ῆς, ἡ</td><td>adjetivo substantivado; nome feminino</td><td>Madalena; mulher de Magdala</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-15\" data-source=\"BDAG\" data-search=\"Μαγεδών remissão veja Ἁρμαγεδ(δ)ών BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μαγεδών</td><td>remissão</td><td>veja Ἁρμαγεδ(δ)ών</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-16\" data-source=\"BDAG\" data-search=\"μαγεία, ας, ἡ substantivo feminino magia; artes mágicas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαγεία, ας, ἡ</td><td>substantivo feminino</td><td>magia; artes mágicas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-17\" data-source=\"BDAG\" data-search=\"μαγεύω verbo praticar magia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαγεύω</td><td>verbo</td><td>praticar magia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-18\" data-source=\"BDAG\" data-search=\"μαγία remissão veja μαγεία BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μαγία</td><td>remissão</td><td>veja μαγεία</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-19\" data-source=\"BDAG\" data-search=\"Μαγνησία, ας, ἡ topônimo feminino Magnésia do Meandro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μαγνησία, ας, ἡ</td><td>topônimo feminino</td><td>Magnésia do Meandro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0222-20\" data-source=\"BDAG\" data-search=\"μάγος, οὑ, ὁ substantivo masculino mago; sacerdote; feiticeiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μάγος, οὑ, ὁ</td><td>substantivo masculino</td><td>mago; sacerdote; feiticeiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0222-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λύτρον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λύτρον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (veja <span class=\"greek\">λύω</span> e o verbete seguinte; Píndaro, Heródoto e outros; ins, pap, LXX, Philo, Joseph.; Mel., P. 91, 684; 103, 792) preço da libertação, resgate (especialmente também o dinheiro de resgate destinado à alforria de escravos, sobretudo no plural: Diod S 19, 85, 3; Polyaenus 4, 10, 1; POxy 48, 6 [86 d.C.]; 49, 8; 722, 30; 40; Mitt-Wilck. II/2, 362, 19; Jos., Ant. 12, 46, mas também no singular: Diod S 20, 84, 6 <span class=\"greek\">δοῦναι</span> <span class=\"greek\">λύτρον</span>; inscrição em KBuresch, Aus Lydien 1898 p. 197 [quanto a essa inscrição e à remissão de Dssm. a ela, veja New Docs 2, 90]; Jos., Ant. 14, 371.—LMitteis, Reichsrecht und Volksrecht 1891, 388; FSteinleitner, Die Beicht 1913, 36ff; 59; 111) entregar a própria vida <span class=\"greek\">λ</span>. <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">πολλῶν</span> como resgate por muitos (veja <span class=\"greek\">πολύς</span> 1a<span class=\"greek\">β</span><span class=\"hebrew\" dir=\"rtl\">א</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:45</a> (BBlake, ET 45, ’34, 142; WHoward, ET 50, ’38, 107–10; JJeremias, Judaica 3, ’48, 249–64; ELohse, Märtyrer u. Gottesknecht, ’55, 116–22; CBarrett, NT Essays: TManson mem. vol. ’59, 1–18 [remete a 2 Macc 7:37].—Cf. Diod S 12, 57, 2; Dio Chrys. 64 [14], 11 <span class=\"greek\">λύτρα</span> <span class=\"greek\">διδόναι</span>; Jos., Ant. 14, 107 <span class=\"greek\">λ</span>. <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">πάντων</span>; Philo Bybl. [séculos I/II d.C.]: 790 Fgm. 3b p. 814, 9 Jac. [em Eus., PE 1, 16, 44] <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">φθορᾶς</span> … <span class=\"greek\">λ</span>.). Deus entregou seu Filho <span class=\"greek\">λ</span>. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἡμῶν</span> como resgate por nós Dg 9:2 (Mel., P. 103, 792 <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">λύτρον</span> <span class=\"greek\">ὑμῶν</span> [<span class=\"greek\">λουτρόν</span> Bodmer]; Lucian, Dial. Deor. 4, 2 <span class=\"greek\">κριὸν</span> <span class=\"greek\">λύτρον</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἐμοῦ</span>; escólio a Nicander, Alexiph. 560 <span class=\"greek\">λύτρα</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">βοῶν</span>; Philo, Spec. Leg. 2, 122; Jos., Ant. 14, 371 <span class=\"greek\">λ</span>. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">αὐτοῦ</span>). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σοὶ</span> <span class=\"greek\">φανερώσει</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">υἱοῖς</span> <span class=\"greek\">Ἰσραήλ</span> por tua causa, o Senhor manifestará ao povo de Israel a salvação (prometida) GJs 7:2. <span class=\"greek\">λ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span>, resgate pelos pecados B 19:10 variante textual.—Veja a bibliografia em <span class=\"greek\">ἀπολύτρωσις</span>, acepção 2, ao final; também NLevinson, SJT 12, ’59, 277–78; DHill, Gk. Words and Heb. Mngs. ’67, 49–81, com correção de perspectiva à luz de novas descobertas New Docs 3, 72–75. Veja SEG XXXIX, ’89, 1863 para uma lista de inscrições.—DELG s.v. <span class=\"greek\">λύω</span>. M-M. EDNT. TW. Spicq (na citação de SB III, 6293, 10 <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">λυτρῶν</span> é uma reconstituição). Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λυτρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λυτρόω</span> (veja o verbete anterior; desde Platão) na literatura aqui considerada, somente na voz média (e passiva) <span class=\"greek\">λυτρόομαι</span> (Demosth.+) futuro médio <span class=\"greek\">λυτρώσομαι</span> LXX; 1º aoristo médio <span class=\"greek\">ἐλυτρωσάμην</span>, imperativo <span class=\"greek\">λύτρωσαι</span>. Na voz passiva: 1º futuro <span class=\"greek\">λυτρωθήσομαι</span> (LXX); 1º aoristo <span class=\"greek\">ἐλυτρώθην</span>; perfeito, 3ª pessoa do singular <span class=\"greek\">λελύτρωται</span>, particípio <span class=\"greek\">λελυτρωμένος</span> LXX.—DELG s.v. <span class=\"greek\">λύω</span>.</p><p class=\"entry-text\">① libertar mediante pagamento de resgate, resgatar</p><p class=\"entry-text\">ⓐ literalmente (Demosth. 19, 170) quanto a prisioneiros (Diod S 5, 17, 3; Jos., Ant. 14, 371) 1 Cl 55:2.</p><p class=\"entry-text\">ⓑ figuradamente <span class=\"greek\">λύτρωσαι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δεσμίους</span> <span class=\"greek\">ἡμῶν</span> (numa oração) 1 Cl 59:4.—Na voz passiva: <span class=\"greek\">ἀργυρίῳ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">χρυσίῳ</span> <span class=\"greek\">λυτρωθῆναι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ματαίας</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἀναστροφῆς</span> ser resgatado com prata ou ouro de vosso modo de vida fútil <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:18</a> (quanto a <span class=\"greek\">λ</span>. <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, veja 2 abaixo.—WvanUnnik, De verlossing <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:18</a>, 19 en het problem van den 1 Pt ’42).</p><p class=\"entry-text\">② libertar de situação opressiva; soltar, salvar, resgatar; extensão figurada da acepção 1 (Ps.-Callisth. 2, 7, 4 <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἑλλάδα</span> <span class=\"greek\">λυτρώσασθαι</span>; 3, 19, 10; LXX; Philo) <span class=\"greek\">τινά</span>, alguém (Iren. 5, 1, 1 [Harv. II 315, 1]) B 14:8. Quanto a Cristo em sua segunda vinda <span class=\"greek\">λυτρώσεται</span> <span class=\"greek\">ἡμᾶς</span> ele nos resgatará 2 Cl 17:4. Quanto ao Messias <span class=\"greek\">ὁ</span> <span class=\"greek\">μέλλων</span> <span class=\"greek\">λυτροῦσθαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰσραήλ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:21</a> (cf. Is 44:22–4; 1 Macc 4:11; PsSol 8:30; 9:1). <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, alguém de alguma coisa (Ps 118:134; cf. antiga oração cristã: CSchmidt, Heinrici Festschr. 1914, p. 69, 32f) <span class=\"greek\">λ</span>. <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ἀνομίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:14</a> (TestJos 18:2 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">κακοῦ</span>). Também <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> (inscrição não bíblica em CB I/2 566f <span class=\"greek\">ἐλυτρώσατο</span> <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">κακῶν</span> <span class=\"greek\">βασάνων</span>; Dt 13:6; Ps 106:2; Sir 51:2; Mel., P. 67, 475 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">λατρείας</span>) alguém de um monstro Hv 4, 1, 7. <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀναγκῶν</span> m 8:10. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span> B 14:5f; cf. v. 7. <span class=\"greek\">ἐκ</span> <span class=\"greek\">θανάτου</span> (Hos 13:14) 19:2. <span class=\"greek\">τ</span>. <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">θανάτου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:19</a> variante textual <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοσούτων</span> <span class=\"greek\">κακῶν</span> AcPl Ha 3, 10.—Na voz passiva: (Aristot., EN 10, 2 [1164b, 34]; LXX; TestJos 18:2; Just., D. 131, 3; Iren. 1, 21, 4 [Harv. I 186, 12]) ser resgatado <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">χάριτι</span> pela graça IPhld 11:1 (quanto a <span class=\"greek\">λ</span>. <span class=\"greek\">ἐν</span>, cf. 2 Esdr 11:10 <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δυνάμει</span>; Ps 76:16; Sir 48:20). <span class=\"greek\">γινώσκομεν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">πόθεν</span> <span class=\"greek\">ἐλυτρώθημεν</span> sabemos, pois, de onde provém nossa redenção B 14:7.—New Docs 3, 72–75. DELG s.v. <span class=\"greek\">λύω</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λύτρωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λύτρωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">λυτρόω</span>; como termo técnico jurídico e comercial em papiros)</p><p class=\"entry-text\">① experiência de libertação de situação opressiva, sentido figurado do uso comercial «resgate de algo por um preço»: resgate, libertação, redenção (Plut., Arat. 11, 2 <span class=\"greek\">λ</span>. <span class=\"greek\">αἰχμαλώτων</span>; Palaeph. exc. Vat. p. 99, 10; LXX; TestJos 8:1) <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">λύτρωσιν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λαῷ</span> realizar a libertação do povo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.68\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:68</a> (cf. TestLevi 2:10, versão armênia; veja Charles). <span class=\"greek\">προσδέχεσθαι</span> <span class=\"greek\">λύτρωσιν</span> <span class=\"greek\">Ἰερουσαλήμ</span> aguardar a redenção de Jerusalém 2:38; <span class=\"greek\">αἰωνία</span> <span class=\"greek\">λ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:12</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἵματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἔσται</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πιστεύουσιν</span> virá a redenção 1 Cl 12:7.</p><p class=\"entry-text\">② abstrato pelo concreto: resgate (quantia de resgate) <span class=\"greek\">δώσεις</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">σου</span> deves oferecer resgate por teus pecados D 4:6; cf. B 19:10.—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λυτρωτής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λυτρωτής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (veja <span class=\"greek\">λυτρόω</span>) redentor, libertador (não encontrado em autores não bíblicos; quanto a Hórus: Iren. 1, 2, 4 [Harv. I 18,4]; LXX quanto a Deus: Ps 18:15; 77:35; AcThom 60 [Aa II/2 p. 177, 11]) quanto a Moisés <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:35</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λυχνία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λυχνία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Hero Alex. I p. 264, 20; Plut., Dio 961 [9, 2]; Ps.-Lucian, Asin. 40; Artem. 1, 74; inscrições; papiros desde PEleph 5, 7 [284/283 a.C.]; LXX, TestAbr; TestJob 32:9; Philo; Joseph. [veja <span class=\"greek\">λύχνος</span>, início]; Just., A I, 26, 7 <span class=\"greek\">λυχνίας</span> … <span class=\"greek\">ἀνατροπήν</span>; veja Phryn. p. 313f Lob.) suporte de lâmpadas sobre o qual se colocavam ou penduravam lâmpadas (veja <span class=\"greek\">λύχνος</span>, início); não um castiçal para velas. <span class=\"greek\">τιθέναι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">λ</span>. (<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">λυχνίας</span>) colocar sobre o suporte (de lâmpadas) (TestAbr B 5 p. 109, 19 [Stone p. 66]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:16</a>; 11:33. Quanto ao candelabro de sete braços (Ex 25:31ff; Jos., Ant. 14, 72) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:2</a>. No Apocalipse, as sete igrejas da Ásia aparecem como sete candelabros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:12f</a>, 20ab; 2:1. Cf. <span class=\"greek\">κινήσω</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">σου</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τόπου</span> <span class=\"greek\">αὐτῆς</span> removerei o teu candelabro do seu lugar, isto é, te excluirei do círculo das igrejas 2:5. O Apocalipse também compara as duas testemunhas de Cristo a dois candelabros 11:4 (cf. Zech 4:11).—DELG s.v. <span class=\"greek\">λύω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λύχνος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λύχνος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (desde Homero; ins, pap, LXX, TestSol, TestAbr, TestJob; TestSim 8:4; ParJer 9:14 [cristão]; Just., D. 10, 1) lâmpada (de metal ou argila [Artem. 2, 9 p. 96, 20f <span class=\"greek\">λύχνος</span> <span class=\"greek\">χαλκοῦς</span>, <span class=\"greek\">ὀστράκινος</span>].—Alimentada a óleo: Posidonius: 87 Fgm. 94 Jac.; Diod S 1, 34, 11; Chariton 1, 1, 15; PGM 7, 359–64. Veja <span class=\"greek\">λυχνία</span>.—<span class=\"greek\">λυχνία</span> ao lado de <span class=\"greek\">λύχνος</span>: Artem. 1, 74 p. 67, 12; IKos 36d, 7; 8; TestAbr B p. 109, 19 [Stone p. 66]; TestJob 32:9; Philo, Spec. Leg. 1, 296 <span class=\"greek\">καίεσθαι</span> <span class=\"greek\">λύχνους</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λυχνίας</span>; Jos., Bell. 7, 429, Ant. 3, 182; 199)</p><p class=\"entry-text\">ⓐ literalmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:36</a>; GPt 5:18. <span class=\"greek\">φῶς</span> <span class=\"greek\">λύχνου</span> (Chariton 1, 1, 15; M. Ant. 12, 15) luz de uma lâmpada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:5</a>; cf. 18:23; <span class=\"greek\">ἔρχεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. traz-se uma lâmpada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:21</a>; <span class=\"greek\">καίειν</span> <span class=\"greek\">λ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:15</a> (Paus. 3, 17, 8 <span class=\"greek\">τὸν</span> <span class=\"greek\">καιόμενον</span> <span class=\"greek\">λύχνον</span>). <span class=\"greek\">λ</span>. <span class=\"greek\">ἅπτειν</span> acender uma lâmpada (<span class=\"greek\">ἅπτω</span> 1.—Como símbolo de algo fora de lugar Paroem. Gr.: Diogenian 6, 27 <span class=\"greek\">λ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">μεσημβρίᾳ</span> <span class=\"greek\">ἅπτειν</span>. De modo semelhante, um poeta cômico desconhecido: Fgm. 721 K.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:16</a>; 11:33; 15:8. <span class=\"greek\">φαί̣ν̣</span>[<span class=\"greek\">ων</span>] <span class=\"greek\">οὐ</span> <span class=\"greek\">λύχνῳ</span> iluminado sem lâmpada AcPl Ha 3, 28f.—Uso da lâmpada como símbolo: <span class=\"greek\">ἔστωσαν</span> <span class=\"greek\">ὑμῶν</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">λύχνοι</span> <span class=\"greek\">καιόμενοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:35</a> (Artem. 2, 9 <span class=\"greek\">λ</span>. <span class=\"greek\">καιόμενος</span>); cf. D 16:1. O Batista como <span class=\"greek\">ὁ</span> <span class=\"greek\">λύχνος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">καιόμενος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">φαίνων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:35</a> (quanto a Cristo <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄσβεστος</span> <span class=\"greek\">λ</span>. ParJer 9:14). Os crentes devem prestar atenção à palavra profética <span class=\"greek\">ὡς</span> <span class=\"greek\">λύχνῳ</span> <span class=\"greek\">φαίνοντι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:19</a> (cf. Ps 118:105 <span class=\"greek\">λύχνος</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">σοῦ</span>).</p><p class=\"entry-text\">ⓑ em sentido metafórico (Lycophron, v. 422 <span class=\"greek\">λύχνοι</span> são os olhos, assim como no verso 846 <span class=\"greek\">λαμπτήρ</span> significa um olho) <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὀφθαλμός</span> a lâmpada do corpo é o olho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:34</a> (FSchwencke, ZWT 55, 1913, 251–60; WBrandt, ZNW 14, 1913, 97–116; 177–201; BBacon, Exp. 8th ser., 7, 1913, 275–88; JDerrett, Law in the NT, ’70, 189–207; GSchneider, Das Bildwort von der Lampe etc., ZNW 61, ’70, 183–209.—Bibliografia adicional no verbete <span class=\"greek\">ἁπλοῦς</span>). Quanto ao Espírito de Deus <span class=\"greek\">λ</span>. <span class=\"greek\">ἐρευνῶν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ταμιεῖα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γαστρός</span> 1 Cl 21:2 (Pr 20:27 A). Quanto à Jerusalém celeste <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀρνίον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:23</a>.—KGalling, D. Beleuchtungsgeräte im isr.-jüd. Kulturgebiet: ZDPV 46, 1923, 1–50; RSmith, BA 27, ’64, 1–31, 101–24; 29, ’66, 2–27.—B. 484; Pauly-W. XIII 1566ff; Kl. Pauly III 478ff. OEANE III 326–30. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λύω</span> imperfeito <span class=\"greek\">ἔλυον</span>; futuro <span class=\"greek\">λύσω</span> LXX; 1º aoristo <span class=\"greek\">ἔλυσα</span>. Na voz passiva: imperfeito <span class=\"greek\">ἐλυόμην</span>; 1º futuro <span class=\"greek\">λυθήσομαι</span>; 1º aoristo <span class=\"greek\">ἐλύθην</span>; perfeito <span class=\"greek\">λέλυμαι</span>, 2ª pessoa do singular <span class=\"greek\">λέλυσαι</span>, particípio <span class=\"greek\">λελυμένος</span> (desde Homero).</p><p class=\"entry-text\">① desfazer algo usado para amarrar ou restringir outra coisa, soltar, desatar vínculos (Da 5:12 Theod.), grilhões (Lucian, Dial. Mar. 14, 3; Job 39:5 <span class=\"greek\">δεσμούς</span>; Philo, Somn. 1, 181; Hippol., Ref. 5, 19, 20) ou algo semelhante.</p><p class=\"entry-text\">ⓐ literalmente, <span class=\"greek\">τὰ</span> <span class=\"greek\">δεσμά</span> AcPl Ha 3, 14; <span class=\"greek\">τὸν</span> <span class=\"greek\">ἱμάντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:27</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ζώνην</span> MPol 13, 2 (JosAs 10:11; 13:3); <span class=\"greek\">σφραγῖδας</span> romper (Polyaenus 5, 2, 12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:2</a>, 5 variante textual (quanto aos selos rompidos de um testamento: BGU 326 II, 21 <span class=\"greek\">ἡ</span> <span class=\"greek\">διαθήκη</span> <span class=\"greek\">ἐλύθη</span>; POxy 715, 19.—<span class=\"greek\">λύω</span> quanto à abertura de um documento: ParJer 7:21 <span class=\"greek\">λῦσον</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπιστολὴν</span> <span class=\"greek\">ταύτην</span>; 7:36; Plut., Dio 31, 4 [uma carta]; Vi. Aesopi W 92 P.)</p><p class=\"entry-text\">ⓑ figuradamente <span class=\"greek\">ἐλύθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δεσμὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γλώσσης</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:35</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.63\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:63</a> D. <span class=\"greek\">λύε</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">σύνδεσμον</span> <span class=\"greek\">ἀδικίας</span> solta toda prisão injusta B 3:3 (Is 58:6).</p><p class=\"entry-text\">② libertar alguém ou algo amarrado ou semelhantemente restringido, soltar, desatar</p><p class=\"entry-text\">ⓐ literalmente, pessoa, animal ou coisa que esteja presa ou amarrada: um prisioneiro (Jos., Bell. 2, 28, Ant. 13, 409; Ps 145:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:30</a>; cf. v. 29, variante textual; ISm 6:2 (cf. b abaixo); AcPl Ha 3, 6. Anjos que estão presos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:14f</a>. Também mais genericamente (IAndrosIsis, Kyme 48 <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δεσμοῖς</span> <span class=\"greek\">λύω</span>) libertar, soltar prisioneiros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:26</a> variante textual; <span class=\"greek\">τοὺς</span> <span class=\"greek\">δεσμίους</span> AcPl Ha 11, 9. Quanto a Satanás, amarrado e aprisionado num abismo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:3</a>. <span class=\"greek\">λυθήσεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σατανᾶς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φυλακῆς</span> <span class=\"greek\">αὐτοῦ</span> v. 7.—Quanto a Lázaro, envolto em faixas mortuárias <span class=\"greek\">λύσατε</span> <span class=\"greek\">αὐτόν</span> desatai-o <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:44</a> (Vi. Aesopi I 83 <span class=\"greek\">λύσατε</span> <span class=\"greek\">αὐτόν</span>=retirai-lhe os grilhões).—Quanto a animais (X., An. 3, 4, 35) um jumentinho amarrado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:2</a>, 4f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:30f</a>, 33ab (talvez essas passagens indiquem uma espécie de requisição de transporte expressa pelo termo <span class=\"greek\">ἀγγαρεύω</span> JDerrett, NovT 13, ’71, 241–58), <span class=\"greek\">τὸν</span> <span class=\"greek\">βοῦν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φάτνης</span> desamarrar o boi da manjedoura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:15</a> (<span class=\"greek\">λ</span>. <span class=\"greek\">ἀπό</span> como em Quint. Smyrn. 4, 373; Is 5:27; Jer 47:4).—<span class=\"greek\">λ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑπόδημα</span> desatar a sandália <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:33</a> (Ex 3:5; Josh 5:15); 13:25.—Na voz passiva, <span class=\"greek\">τὰς</span> <span class=\"greek\">τρίχας</span> <span class=\"greek\">λελυμέναι</span>, com cabelos soltos Hs 9, 9, 5; cf. <span class=\"greek\">τὰς</span> <span class=\"greek\">τρίχας</span> <span class=\"greek\">λελυμένας</span> Hs 9, 13, 8.</p><p class=\"entry-text\">ⓑ figuradamente, libertar, soltar, deixar livre <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (TestJos 15:6; Cyranides p. 97, 12) <span class=\"greek\">λυθῆναι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δεσμοῦ</span> <span class=\"greek\">τούτου</span> ser liberto desse vínculo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:16</a>. <span class=\"greek\">λέλυσαι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">γυναικός</span>; estás livre de mulher, isto é, não estás ligado a uma esposa? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:27</a> (não é necessário pressupor um estado anterior de «ligação»; cf. Chion, Ep. 7, 3 <span class=\"greek\">λελυμένως</span>=[falar] sem restrições. Veja também Simplicius em Epict. p. 129, 3: ‘quem não constitui família é <span class=\"greek\">εὔλυτος</span>’, isto é, livre). O particípio perfeito passivo IMg 12:1 é a negação de <span class=\"greek\">δέδεμαι</span>, isto é, desatado. Quanto a ISm 6:2, veja o comentário de WBauer. <span class=\"greek\">ἐκ</span> em lugar de <span class=\"greek\">ἀπό</span>: <span class=\"greek\">λ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span> libertar alguém dos pecados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:5</a>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">χειρὸς</span> <span class=\"greek\">σιδήρου</span> 1 Cl 56:9 (Job 5:20). Quanto a vínculos que prendem pessoas, desfazer, remover (<span class=\"greek\">Χριστὸς</span>) <span class=\"greek\">λύσει</span> <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">δεσμόν</span> IPhld 8:1.</p><p class=\"entry-text\">③ reduzir alguma coisa violentamente aos seus componentes, destruir (Iren. 1, 8, 1 [Harv. I 67, 9]), quanto a construção, demolir (Il. 16, 10; X., An. 2, 4, 17f; Herodian 7, 1, 7; 1 Esdr 1:52; Jos., Bell. 6, 32; SibOr 3, 409) <span class=\"greek\">τ</span>. <span class=\"greek\">ναὸν</span> <span class=\"greek\">τοῦτον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:19</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">μεσότοιχον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:14</a> (em linguagem figurada).—<span class=\"greek\">ἡ</span> <span class=\"greek\">πρύμνα</span> <span class=\"greek\">ἐλύετο</span> a popa começou a desfazer-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:41</a> (PLond III 1164h, 19 p. 164 [século III d.C.] emprega <span class=\"greek\">λ</span>. para o desmantelamento de um navio). Quanto aos componentes do universo, desfeitos e destruídos na conflagração final <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:10</a>–12 (cf. Just., D. 5, 4; Tat. 25, 2).—Quanto a uma reunião (Il. 1, 305; Od. 2, 257; Apollon. Rhod. 1, 708; X., Cyr. 6, 1, 2; Diod S 19, 25, 7; EpArist 202; Jos., Ant. 14, 388 <span class=\"greek\">λυθείσης</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βουλῆς</span>) <span class=\"greek\">λυθείσης</span> <span class=\"greek\">τ</span>. <span class=\"greek\">συναγωγῆς</span> quando a reunião da sinagoga havia terminado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:43</a>.—<span class=\"greek\">λυθεῖσα</span> Ox 1081, 3, conforme editado (assim também Otero I 82, no. 3) foi lido incorretamente em lugar de <span class=\"greek\">ἐ</span>]<span class=\"greek\">ληλύθεισαν</span>, veja o verbete <span class=\"greek\">ἔρχομαι</span> 1a<span class=\"greek\">ζ</span>.</p><p class=\"entry-text\">④ eliminar, destruir, pôr fim a, abolir (Socrat., Ep. 28, 2 e 4 «dissipar» calúnias; Tat. 13, 1 <span class=\"greek\">ψυχὴ</span> … <span class=\"greek\">λύεται</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span>; Mel., P. 43, 301 <span class=\"greek\">ὁ</span> <span class=\"greek\">τύπος</span> <span class=\"greek\">ἐλύθη</span>=o tipo foi abolido [quando o antítipo se manifestou]) <span class=\"greek\">λ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">διαβόλου</span> destruir as obras do diabo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:8</a>. Na voz passiva, <span class=\"greek\">ἐλύετο</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">μαγεία</span>, toda magia começou a desfazer-se IEph 19:3. <span class=\"greek\">λύεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὄλεθρος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὁμονοίᾳ</span> sua ação destrutiva termina pela união 13:1.—<span class=\"greek\">λ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">ὠδῖνας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θανάτου</span> deve significar, no contexto: (Deus) pôs fim às dores (IG IV2, 128, 49 [280 a.C.] <span class=\"greek\">ἔλυσεν</span> <span class=\"greek\">ὠδῖνα</span>; Lycophron vs. 1198 <span class=\"greek\">ὠδῖνας</span> <span class=\"greek\">ἐξέλυσε</span> <span class=\"greek\">γονῆς</span>; Himerius, Or. 64 [=Or. 18], 1 <span class=\"greek\">λυθῆναι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὠδῖνας</span> quanto à cessação das dores do parto; Job 39:2; Aelian, HA 12, 5 <span class=\"greek\">τοὺς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὠδίνων</span> <span class=\"greek\">λῦσαι</span> <span class=\"greek\">δεσμούς</span>; Eutecnius 3 p. 30, 26), para que o «nascimento» que há de trazer Cristo à luz possa alcançar sua finalidade (Haenchen no lugar citado) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:24</a> (mas veja <span class=\"greek\">θάνατος</span> 1b<span class=\"greek\">β</span>; originalmente é provável que «os laços da morte» estivessem associados a «soltar»); Pol 1:2.—Quanto a mandamentos, leis e declarações: revogar, anular, abolir (Hdt. 1, 29, 1 <span class=\"greek\">νόμον</span>. Texto proveniente de Nisa em Diod S 1, 27, 4 <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ἐνομοθέτησα</span>, <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">αὐτὰ</span> <span class=\"greek\">δύναται</span> <span class=\"greek\">λῦσαι</span>; Ael. Aristid. 30 p. 573 D.: <span class=\"greek\">νόμους</span>; Achilles Tat. 3, 3, 5; SIG 355, 21; 1219, 12; Jos., Ant. 11, 140) <span class=\"greek\">ἐντολήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:19</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">σάββατον</span> abolir o sábado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:18</a> (em João, Jesus é acusado não de violar o sábado, mas de suprimi-lo como ordenança). Na voz passiva (Dio Chrys. 58 [75], 10 <span class=\"greek\">τ</span>. <span class=\"greek\">νόμου</span> <span class=\"greek\">λυθέντος</span>) 7:23; 10:35 (RJungkuntz, CTM 35, ’64, 556–65 [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:34</a>–6]).—<span class=\"greek\">λύειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span> anular (o verdadeiro ensino sobre) Jesus (rejeitando-o); (cf. Alex. Aphr., Fat. 26, II 2 p. 196, 18 <span class=\"greek\">λ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ζήνωνος</span> <span class=\"greek\">λόγων</span>=certos ensinamentos de Zenão; em oposição a <span class=\"greek\">ὁμολογεῖν</span>: veja Iren. 1, 9, 3 [Harv. I 85, 10]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:3</a> variante textual (quanto à leitura <span class=\"greek\">λύει</span>, veja Iren. 3, 16, 8 [Harv. II 90, 3]; Cl. Al., Fgm. 35 p. 218, 10ff Stählin; Orig. XI [GCS] 152, 28; Socrates, HE 7, 32; EHarnack, SBBerlAk 1915, 556–61=Studien I ’31, 132–37; A Rahlfs, TLZ 40, 1915, 525; OPiper, JBL 66, ’47, 440–44 [exorcístico, desfazer um encantamento]).</p><p class=\"entry-text\">⑤ Sobre a combinação e o contraste entre <span class=\"greek\">δέειν</span> e <span class=\"greek\">λύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:19</a>; 18:18, veja <span class=\"greek\">δέω</span> 4; também GLambert, Vivre et Penser, IIIe s., ’43/44, 91–103.—B. 1239f. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λωί̈ς, ί̈δος, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λωί̈ς</span>, <span class=\"greek\">ί̈δος</span>, <span class=\"greek\">ἡ</span> (PPetr II, 39b, 15 [século III a.C.] apresenta o genitivo <span class=\"greek\">Λωϊτος</span> de um nominativo <span class=\"greek\">Λωϊς</span>. Ou será que o nome — não encontrado em outro lugar — corresponde ao grau positivo de comparação <span class=\"greek\">λῶϊς</span> [proposto por Buttmann para o relativamente comum <span class=\"greek\">λωί̈ων</span>, nominativo singular, «mais agradável, mais desejável»]? Cf. Semonides 7, 30 D.3 [=West p. 102] <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ἄλλη</span> <span class=\"greek\">τῆσδε</span> <span class=\"greek\">λωί̈ων</span> <span class=\"greek\">γυνή</span>=nenhuma outra mulher é mais digna de ser desejada do que esta.) Loide, avó de Timóteo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:5</a>.—BHHW II 1103.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λώτ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λώτ</span>, <span class=\"greek\">ὁ</span> indeclinável (<span class=\"hebrew\" dir=\"rtl\">לוֹט</span>.—LXX, TestAbr, Philo.—Em Josefo <span class=\"greek\">Λῶτος</span>, <span class=\"greek\">ου</span> [Ant. 1, 201]) Ló, filho de Harã, sobrinho de Abraão (Gen 11:27); ele viveu em Sodoma <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:28f</a>; foi salvo daquela cidade condenada, tendo levado vida virtuosa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:7</a>; 1 Cl 11:1 (SRappaport, D. gerechte Lot: ZNW 29, 1930, 299–304). Sua mulher pereceu porque, ao deixar a cidade, olhou para trás, contrariando a ordem de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:32</a> (quanto ao conjunto, veja Gen 19). Sua separação de Abraão 1 Cl 10:4 (veja Gen 13, especialmente os versículos 14–16).—(Quanto à grafia, veja JWordsworth-HWhite sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:17</a>.)—BHHW II 1105f. DELG.</p><p class=\"entry-text\"><span class=\"greek\">Μ</span></p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μ´</h1><div class=\"entry-meta\"><span>sinal numérico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μ</span>´ sinal numérico = 40 (<span class=\"greek\">τεσσε</span>[<span class=\"greek\">α</span>]<span class=\"greek\">ράκοντα</span>; Diod S 22, 13, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:41</a> D; Hs 9, 4, 3; 9, 5, 4; 9, 15, 4; 9, 16, 5; GJs 1:4 Bodmer.—Pauly-W. XVI 1661.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μάαθ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μάαθ</span>, <span class=\"greek\">ὁ</span> indeclinável (cf. o nome <span class=\"hebrew\" dir=\"rtl\">מַחַת</span> 1 Ch 6:20 [<span class=\"greek\">Μεθ</span>]; 2 Ch 29:12 [<span class=\"greek\">Μααθ</span>]; 31:13) Maat, na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:26</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μαγαδάν, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μαγαδάν</span>, <span class=\"greek\">ἡ</span> indeclinável Magadã, lugar de localização incerta junto ao lago de Genesaré <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:10</a> variante textual; a passagem paralela apresenta <span class=\"greek\">Δαλμανουθά</span> (veja esse verbete), cuja localização também é incerta. Outras variantes textuais para ambas as passagens: <span class=\"greek\">Μαγαδά</span>, <span class=\"greek\">Μαγεδά</span> (-<span class=\"greek\">άν</span>), <span class=\"greek\">Μαγδαλά</span> (-<span class=\"greek\">άν</span>); quanto a Marcos: (<span class=\"greek\">Μελεγαδά</span> [D]).—JBoehmer, ZNW 9, 1908, 227–29; CKopp, Dominican Studies 4, ’50, 344–50; BHHW II 1121; OEANE III 399f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μαγδαλά(ν)</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μαγδαλά</span>(<span class=\"greek\">ν</span>) veja <span class=\"greek\">Μαγαδάν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μαγδαληνή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>adjetivo substantivado; nome feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μαγδαληνή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (substantivo feminino de <span class=\"greek\">Μαγδαληνός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span>) mulher de Magdala, Madalena, designação de certa Maria (veja <span class=\"greek\">Μαρία</span> 2), provavelmente proveniente da cidade de Magdala, que, segundo o Talmude, ficava a cerca de vinte minutos de caminhada de Tiberíades, na margem ocidental do lago de Genesaré (veja <span class=\"greek\">Μαγαδάν</span>; Buhl 225f; CKopp, The Holy Places of the Gospels, traduzido por RWalls, ’63, 190–97) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:56</a>, 61; 28:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:40</a>, 47; 16:1, 9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:2</a>; 24:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:25</a>; 20:1, 18; GPt 12:50.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μαγεδών</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μαγεδών</span> veja <span class=\"greek\">Ἁρμαγεδ</span>(<span class=\"greek\">δ</span>)<span class=\"greek\">ών</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαγεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαγεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja o verbete seguinte e <span class=\"greek\">μάγος</span>; Platão e outros; quanto à grafia, veja B-D-F §23; veja Mlt-H. 339) rito ou conjunto de ritos que normalmente empregam encantamentos para influenciar ou controlar poderes transcendentes, magia (Theophr., HP 9, 15, 7; Vett. Val. 210, 4; IDefixWünsch 4, 15; PGM 1, 127; Zosimus 7: Herm. Wr. IV p. 105 Sc.; o documento hermético <span class=\"greek\">Κόρη</span> <span class=\"greek\">κόσμου</span> em Stob. I 407, 4 W.=p. 494, 7 Sc.; Jos., Ant. 2, 286) em lista de vícios 20:1 (AscIs 2:5 <span class=\"greek\">μαγεία</span> com <span class=\"greek\">φαρμακεία</span> e outros vícios). <span class=\"greek\">ἐλύετο</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">μαγεία</span> IEph 19:3 (<span class=\"greek\">λύω</span> 4). No plural: artes mágicas (Jos., Ant. 2, 284) em lista de vícios D 5:1. Quanto a Simão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:11</a> (cf. PGM 4, 2447ff: <span class=\"greek\">Παχράτης</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">προφήτης</span> <span class=\"greek\">Ἡλιουπόλεως</span>, <span class=\"greek\">Ἁδριανῷ</span> <span class=\"greek\">βασιλεῖ</span> <span class=\"greek\">ἐπιδεικνύμενος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">δύναμιν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θείας</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">μαγείας</span> ‘Pacrates, profeta de Heliópolis, demonstrando o poder de sua magia divina’).—R. Kotansky, Israel Exploration Journal 41, ’91, 267–81, amuletos empregados em orações aos anjos; Kl. Pauly III 873f. Bibliografia no verbete <span class=\"greek\">Σίμων</span> 9.—B. 1494. DELG s.v. <span class=\"greek\">μάγος</span>. <span class=\"greek\">Μ</span>-<span class=\"greek\">Μ</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαγεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαγεύω</span> futuro <span class=\"greek\">μαγεύσω</span> praticar magia (veja o verbete anterior e <span class=\"greek\">μάγος</span>; Eur., Iph. 1338; TestSol 15:5 [na voz passiva]; Tat. 1, 1; Plut., Artax. 3, 6, Numa 15, 8; inscrição greco-aramaica em CClemen, D. Einfluss d. Mysterienreligionen auf d. älteste Christentum 1913 p. 10, 3 <span class=\"greek\">στρατηγὸς</span> … <span class=\"greek\">ἐμάγευσε</span> <span class=\"greek\">Μίθρῃ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:9</a> (JFossum, Simon Magus: 1473–77). Em lista de vícios D 2:2.—DELG s.v. <span class=\"greek\">μάγος</span>. <span class=\"greek\">Μ</span>-<span class=\"greek\">Μ</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μαγία</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μαγία</span> veja <span class=\"greek\">μαγεία</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μαγνησία, ας, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μαγνησία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Heródoto e outros; ins) Magnésia, cidade da Ásia Menor situada a pouca distância a sudeste de Éfeso, conforme a inscrição IMg. Um templo de Ártemis era um de seus ornamentos. Para distinguir essa cidade da Magnésia da Tessália, considerada sua metrópole (OGI 503 <span class=\"greek\">Μάγνητες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Μαιάνδρῳ</span> <span class=\"greek\">ποταμῷ</span>, <span class=\"greek\">ἄποικοι</span> <span class=\"greek\">ὄντες</span> <span class=\"greek\">Μαγνήτων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Θεσσαλίᾳ</span>, veja também as notas; SIG 636 e 1157), e de outra Magnésia na Ásia Menor, próxima do monte Sípilo (OGI 501, 13; 229 veja a nota 12; quanto à inscrição, veja IMagnSip), ela é chamada Magnésia do Meandro, embora esteja junto ao Leteu, a cerca de 6½ km do Meandro. O nome do rio costuma ser acrescentado com preposição; na passagem considerada, <span class=\"greek\">πρός</span> com dativo, como também em OGI 229, 84; 503 (veja acima); IMagnMai 40, 11 e 16; 44, 4; 101, 8. Um habitante da cidade é chamado <span class=\"greek\">Μάγνης</span>, <span class=\"greek\">ητος</span> (Heródoto e outros na literatura; também em inscrições e moedas [cf. o material em Lghtf. sobre a inscrição IMg; também OGI 12; 231; 232; 234; 319; 501. Quanto às referências ao nome, veja o índice III de IMagnMai p. 206]); não <span class=\"greek\">Μαγνησιεύς</span> (variante textual) nem <span class=\"greek\">Μαγνήσιος</span> (a forma mais extensa em Inácio).—Pauly-W. XIV 471f; Kl. Pauly III 885f. PECS 544.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0222-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μάγος, οὑ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μάγος</span>, <span class=\"greek\">οὑ</span>, <span class=\"greek\">ὁ</span> (veja <span class=\"greek\">μαγεία</span>, <span class=\"greek\">μαγεύω</span>)</p><p class=\"entry-text\">① mago, sacerdote e sábio (persa [SNyberg, D. Rel. d. alten Iran ’38], posteriormente também babilônico), especializado em astrologia, interpretação de sonhos e diversas outras artes ocultas (assim desde Heródoto; Jos., Ant. 20, 142; veja Da 2:2, 10; também em outras passagens de Da, segundo Teodocião; Tat. 28, 1. Ao lado de <span class=\"greek\">φιλόσοφος</span>, quanto a Apolônio de Tiana: Orig., C. Cels. 6, 41, 13). Após o nascimento de Jesus <span class=\"greek\">μάγοι</span>, magos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:7</a> (cf. Jos., Ant. 10, 216), 16a (=GJs 22:1); v. 16b; GJs 21:1, 3 (à parte do texto em papiro, <span class=\"greek\">μάγοι</span> aparece duas vezes nos códices de GJs em 21:2; uma vez no v. 3), ou, de forma mais precisa <span class=\"greek\">μάγοι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἀνατολῶν</span> (<span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἀρραβίας</span> Just., D. 77, 4; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἀνάτολῆς</span> Orig., C. Cels. 1, 40, 20) magos do Oriente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:1</a> vieram à Palestina e declararam ter reconhecido nas estrelas o nascimento do Rei messiânico. Diog. L. 2, 45 <span class=\"greek\">φησὶ</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">Ἀριστοτέλης</span> <span class=\"greek\">μάγον</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐλθόντα</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">Συρίας</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἀθήνας</span> para anunciar a Sócrates que ele teria uma morte violenta.—ADieterich, ZNW 3, 1902, 1–14; FSteinmetzer, D. Gesch. der Geburt u. Kindheit Christi 1910; GFrenken, Wunder u. Taten der Heiligen 1929, 186–93; KBornhäuser, D. Geburts-u. Kindheitsgesch. Jesu 1930. FCumont, L’Adoration des Mages: Memorie della Pontif. Acc. Rom. di Archeol. 3, ’32, 81–105. EHodous, CBQ 6, ’44, 71–74; 77–83.—Sobre os magos HMeyboom, Magiërs: TT ’39, 1905, 40–70; GMessina, D. Ursprung der Magier u. d. zarath. Rel., diss. Berl. 1930, I Magi a Betlemme e una predizione di Zoroastro ’33 (em oposição a ele, GHartmann, Scholastik 7, ’32, 403–14); RPettazzoni, RHR 103, ’31, 144–50; Goodsp., Probs. 14f.—Sobre a estrela dos magos HKritzinger, Der Stern der Weisen 1911; HGVoigt, Die Geschichte Jesu u. d. Astrologie 1911; OGerhardt, Der Stern des Messias 1922; DFrövig, D. Stern Bethlehems in der theol. Forschung: TK 2, ’31, 127–62; CSSmith, CQR 114, ’32, 212–27; WVischer, D. Ev. von den Weisen aus dem Morgenlande: EVischer Festschr. ’35, 7–20; ELohmeyer, D. Stern d. Weisen: ThBl 17, ’38, 288–99; GHartmann, Stimmen d. Zeit 138, ’41, 234–38; JSchaumberger, Ein neues Keilschriftfragment über d. angebl. Stern der Weisen: Biblica 24, ’43, 162–69, mas veja ASachs e CWalker, Kepler’s View of the Star of Bethlehem and the Babylonian Almanac for 7/6 b.c.: Iraq 46/1, ’84, 43–55. Cf. <span class=\"greek\">ποιμήν</span> 1.</p><p class=\"entry-text\">② mágico, feiticeiro (trágicos e outros; Aeschin. 3, 137 [<span class=\"greek\">μάγος</span>=<span class=\"greek\">πονηρός</span>]; Diod S 5, 55, 3; 34 + 35 Fgm. 2, 5 <span class=\"greek\">τὶς</span> … <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">μάγος</span>, falso profeta, que <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">ἐξηπάτα</span>; Vett. Val. 74, 17; Philo, Spec. Leg. 3, 93; TestReub 4:9) quanto a Barjesus, isto é, Elimas, em Chipre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:6</a>, 8. Cf. Hm 11:2, variante textual.—Sobre a história da palavra ANock, Beginn. I 5, ’33, 164–88=Essays I 308–30; HKippenberg, Garizim u. Synagoge ’71, 122–24 sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:10</a>; MMeyer/PMirecki, edd., Ancient Magic and Ritual Power ’95. M-LThomsen, Zauberdiagnose und Schwarze Magie in Mesopotamien (CNI Publikations 2), sem data: contexto mesopotâmico antigo. Veja também MSmith, Clement of Alexandria and a Secret Gospel of Mark ’73, especialmente 220–78 quanto às fontes antigas e 423–44 quanto à bibliografia (quanto à cautela diante do sensacionalismo midiático e de hipóteses fantasiosas relativas a essa obra, veja JFitzmyer, How to Exploit a Secret Gospel: America, June 23, ’73, 570–72). FGraf, La magie dans l’ antiquité Gréco-Romaine, ’95.—B. 1494f. Renehan ’82, no verbete DELG. M-M. TW.</p></section></article>"};
